#!/usr/bin/env python3
"""Test for callable instance support in CLI - this should be integrated into the main test suite."""

import unittest
from dataclasses import dataclass
from jsonargparse import CLI
from jsonargparse_tests.base import TempDirTestCase


@dataclass
class CallableInstance:
    """A callable instance for testing CLI support."""
    multiplier: int = 1

    def __call__(self, x: int):
        return x * self.multiplier


class CallableInstanceTests(TempDirTestCase):

    def test_callable_instance_with_keyword_args(self):
        """Test that callable instances work with keyword arguments."""
        f = CallableInstance(multiplier=2)
        result = CLI(f, args=['--x', '21'], as_positional=False)
        self.assertEqual(result, 42)

    def test_callable_instance_with_positional_args(self):
        """Test that callable instances work with positional arguments."""
        f = CallableInstance(multiplier=3)
        result = CLI(f, args=['10'])  # positional argument
        self.assertEqual(result, 30)

    def test_callable_instance_help(self):
        """Test that help works for callable instances."""
        f = CallableInstance()
        with self.assertRaises(SystemExit):
            CLI(f, args=['--help'], as_positional=False)


if __name__ == '__main__':
    unittest.main()

