"""
Comprehensive test to verify the fix handles various edge cases properly.
"""

from haystack import Document
from haystack.nodes.other.join_docs import JoinDocuments


def test_all_none_scores():
    """Test with all documents having None scores"""
    print("Testing with all documents having None scores...")

    inputs = [
        {"documents": [
            Document(content="doc1", score=None),
            Document(content="doc2", score=None)
        ]},
        {"documents": [
            Document(content="doc3", score=None)
        ]}
    ]

    join_docs = JoinDocuments(join_mode="concatenate", sort_by_score=False)
    result, _ = join_docs.run(inputs)
    print(f"SUCCESS: {len(result['documents'])} documents returned")
    for doc in result['documents']:
        print(f"  - '{doc.content}': {doc.score}")
    return True


def test_mixed_scores_with_duplicates():
    """Test mixed scenario with various combinations"""
    print("\nTesting mixed scores with duplicates...")

    inputs = [
        {"documents": [
            Document(id="1", content="doc1", score=0.8),
            Document(id="2", content="doc2", score=None),
            Document(id="3", content="doc3", score=0.3)
        ]},
        {"documents": [
            Document(id="2", content="doc2_duplicate", score=0.5),  # Better score than None
            Document(id="4", content="doc4", score=None)
        ]}
    ]

    join_docs = JoinDocuments(join_mode="concatenate", sort_by_score=False)
    result, _ = join_docs.run(inputs)
    print(f"SUCCESS: {len(result['documents'])} documents returned")
    for doc in result['documents']:
        print(f"  - ID:{doc.id} '{doc.content}': {doc.score}")
    return True


def test_negative_scores():
    """Test with negative scores"""
    print("\nTesting with negative scores...")

    inputs = [
        {"documents": [
            Document(id="1", content="doc1", score=-0.5),
            Document(id="2", content="doc2", score=None)
        ]},
        {"documents": [
            Document(id="2", content="doc2_better", score=-0.1),  # Better than -0.5
        ]}
    ]

    join_docs = JoinDocuments(join_mode="concatenate", sort_by_score=False)
    result, _ = join_docs.run(inputs)
    print(f"SUCCESS: {len(result['documents'])} documents returned")
    for doc in result['documents']:
        print(f"  - ID:{doc.id} '{doc.content}': {doc.score}")
    return True


def test_zero_vs_none_scores():
    """Test zero vs None scores"""
    print("\nTesting zero vs None scores...")

    inputs = [
        {"documents": [
            Document(id="1", content="doc1", score=0.0),
            Document(id="2", content="doc2", score=None)
        ]},
        {"documents": [
            Document(id="2", content="doc2_better", score=0.1),  # Better than 0.0
        ]}
    ]

    join_docs = JoinDocuments(join_mode="concatenate", sort_by_score=False)
    result, _ = join_docs.run(inputs)
    print(f"SUCCESS: {len(result['documents'])} documents returned")
    for doc in result['documents']:
        print(f"  - ID:{doc.id} '{doc.content}': {doc.score}")
    return True


def test_sort_by_score_true_with_none():
    """Test that sort_by_score=True still works correctly with None scores"""
    print("\nTesting sort_by_score=True with None scores...")

    inputs = [
        {"documents": [
            Document(id="1", content="lowest", score=0.1),
            Document(id="2", content="none_score", score=None),
            Document(id="3", content="highest", score=0.9)
        ]},
        {"documents": [
            Document(id="2", content="none_score_dup", score=0.5),  # Better than None
        ]}
    ]

    join_docs = JoinDocuments(join_mode="concatenate", sort_by_score=True)
    result, _ = join_docs.run(inputs)
    print(f"SUCCESS: {len(result['documents'])} documents returned (sorted)")
    for doc in result['documents']:
        print(f"  - ID:{doc.id} '{doc.content}': {doc.score}")
    return True


if __name__ == "__main__":
    print("=" * 60)
    print("COMPREHENSIVE TESTING OF JOIN DOCUMENTS FIX")
    print("=" * 60)

    tests = [
        test_all_none_scores,
        test_mixed_scores_with_duplicates,
        test_negative_scores,
        test_zero_vs_none_scores,
        test_sort_by_score_true_with_none,
    ]

    results = []
    for test in tests:
        try:
            result = test()
            results.append(("PASS", test.__name__))
        except Exception as e:
            print(f"FAILED: {test.__name__}: {e}")
            results.append(("FAIL", test.__name__))

    print("\n" + "=" * 60)
    print("SUMMARY:")
    for status, name in results:
        print(f"  {name}: {status}")
    print("=" * 60)

