from haystack import Document
from haystack.nodes.other.join_docs import JoinDocuments


def test_exact_issue_scenario():
    """
    Test the exact scenario from the GitHub issue:
    - Some documents without scores (score=None)
    - Using JoinDocuments with sort_by_score=False
    - Should not error out
    """
    print("Testing exact issue scenario...")

    # Create documents similar to what would cause the issue
    inputs = [
        {
            "documents": [
                Document(content="Zoltan Fedor is the Director, AI Platform...", score=0.85),
                Document(content="Another document with no score", score=None),  # This would cause the issue
            ]
        },
        {
            "documents": [
                Document(content="Third document", score=0.65),
                Document(content="Another document with no score", score=0.4),  # Same content as above but with score
            ]
        }
    ]

    # This is the exact usage pattern that was failing
    join_docs = JoinDocuments(sort_by_score=False)

    try:
        result, _ = join_docs.run(inputs)
        print("✅ SUCCESS: JoinDocuments worked with documents without scores!")
        print(f"Returned {len(result['documents'])} documents:")
        for i, doc in enumerate(result['documents']):
            print(f"  {i+1}. Content: '{doc.content[:50]}...' Score: {doc.score}")
        return True
    except Exception as e:
        print(f"❌ FAILED: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()
        return False


