        print("✅ SUCCESS: JoinDocuments worked with sort_by_score=True too!")
        print(f"Returned {len(result['documents'])} documents (sorted):")
        for i, doc in enumerate(result['documents']):
            print(f"  {i+1}. Content: '{doc.content[:50]}...' Score: {doc.score}")
        return True
    except Exception as e:
        print(f"❌ FAILED: {type(e).__name__}: {e}")
        return False


if __name__ == "__main__":
    print("=" * 70)
    print("FINAL VERIFICATION OF GITHUB ISSUE FIX")
    print("=" * 70)

    success1 = test_exact_issue_scenario()
    success2 = test_with_sort_by_score_true_as_well()

    print("\n" + "=" * 70)
