def statements(self) -> List[str]:
    from sqlparse.tokens import Whitespace, Comment

    result = []
    for stmt in self.statements_parsed:
        # Filter out statements that contain only whitespace and comments
        meaningful_tokens = [
            token for token in stmt.tokens 
            if not token.is_whitespace and token.ttype not in (Comment.Single, Comment.Multiline)
        ]
        if meaningful_tokens:
            result.append(sqlparse.format(stmt.value))
    return result

