import anyio
from exceptiongroup import BaseExceptionGroup

def test_debug_mixed():
    """Debug mixed exceptions."""
    print("=== Debug: Mixed exceptions ===")

    async def _test():
        try:
            async with anyio.create_task_group() as tg:
                tg.cancel_scope.cancel()
                try:
                    await anyio.sleep_forever()
                except anyio.get_cancelled_exc_class() as exc:
                    print(f"Caught cancellation: {type(exc)}")
                    # Create a mixed BaseExceptionGroup
                    other_exc = ValueError("other error")
                    wrapped = BaseExceptionGroup("mixed", [exc, other_exc])
                    print(f"Wrapped in group with {len(wrapped.exceptions)} exceptions:")
                    for i, e in enumerate(wrapped.exceptions):
                        print(f"  {i}: {type(e).__name__}: {e}")
                    raise wrapped
            print("UNEXPECTED: No exception raised")
        except BaseException as e:
            print(f"Got exception: {type(e).__name__}: {e}")
            if hasattr(e, 'exceptions'):
                print(f"  Contains {len(e.exceptions)} sub-exceptions:")
                for i, sub in enumerate(e.exceptions):
                    print(f"    {i}: {type(sub).__name__}: {sub}")

    anyio.run(_test, backend="asyncio")

if __name__ == "__main__":
    test_debug_mixed()

import anyio
from exceptiongroup import BaseExceptionGroup

def test_debug_nested():
    """Debug nested exception groups with pure cancellations."""
    print("=== Debug: Nested pure cancellations ===")

    async def _test():
        try:
            async with anyio.create_task_group() as tg:
                tg.cancel_scope.cancel()
                try:
                    await anyio.sleep_forever()
                except anyio.get_cancelled_exc_class() as exc:
                    print(f"Caught cancellation: {type(exc)}")
                    # Create nested BaseExceptionGroups with ONLY cancellations
                    inner_group = BaseExceptionGroup("inner", [exc])
                    outer_group = BaseExceptionGroup("outer", [inner_group])
                    print(f"Inner group: {inner_group} with {len(inner_group.exceptions)} exceptions")
                    print(f"Outer group: {outer_group} with {len(outer_group.exceptions)} exceptions")
                    for i, e in enumerate(outer_group.exceptions):
                        print(f"  Outer[{i}]: {type(e)} - {e}")
                        if hasattr(e, 'exceptions'):
                            for j, sub in enumerate(e.exceptions):
                                print(f"    Inner[{j}]: {type(sub)} - {sub}")
                    raise outer_group
            print("SUCCESS: No exception raised (pure cancellations handled)")
        except BaseException as e:
            print(f"Got exception: {type(e).__name__}: {e}")
            if hasattr(e, 'exceptions'):
                print(f"  Contains {len(e.exceptions)} sub-exceptions:")
                for i, sub in enumerate(e.exceptions):
                    print(f"    {i}: {type(sub).__name__}: {sub}")
                    if hasattr(sub, 'exceptions'):
                        print(f"      Sub contains {len(sub.exceptions)} exceptions")
                        for j, subsub in enumerate(sub.exceptions):
                            print(f"        {j}: {type(subsub).__name__}: {subsub}")

    anyio.run(_test, backend="asyncio")

if __name__ == "__main__":
    test_debug_nested()

