#!/usr/bin/env python3
"""
Debug the detection logic
"""

from pyteal import *

@Subroutine(TealType.uint64)
def factorial(i: Expr) -> Expr:
    return If(i <= Int(1), Int(1), factorial_intermediate(i - Int(1), Bytes("inconsequential")) * i)

@Subroutine(TealType.uint64)
def factorial_intermediate(i: Expr, j: Expr) -> Expr:
    return Seq(Log(j), factorial(i))

def main():
    program = Return(factorial(Int(4)) == Int(24))

    # Compile with version 5 (as in the issue)
    teal = compileTeal(program, Mode.Application, version=5)
    lines = teal.split('\n')

    print("All lines with 'callsub':")
    for i, line in enumerate(lines):
        if 'callsub' in line:
            print(f"{i:2}: {line}")
            # Show context
            start = max(0, i-3)
            end = min(len(lines), i+2)
            for j in range(start, end):
                marker = ">>> " if j == i else "    "
                print(f"    {marker}{j:2}: {lines[j]}")
            print()

if __name__ == "__main__":
    main()

