def process_zip_code(zip_code):
    """
    Process ZIP codes to handle ZIP+4 format.

    Args:
        zip_code (str): ZIP code, potentially in ZIP+4 format (e.g., "12345-6789")

    Returns:
        str: 5-digit ZIP code (e.g., "12345")
    """
    if zip_code is None:
        return None

    # If it contains a hyphen, extract only the first part (5-digit ZIP)
    if '-' in zip_code:
        return zip_code.split('-')[0]

    # Otherwise return as-is (should already be 5 digits)
    return zip_code

