#!/usr/bin/env python3
"""Comprehensive test for subtest functionality."""

import unittest
import tempfile
import os
import shutil
from tap import TAPTestRunner


class ComprehensiveSubTestTest(unittest.TestCase):
    """Comprehensive test cases for subtest functionality."""

    def test_all_passing_subtests(self):
        """All subtests pass."""
        for i in range(3):
            with self.subTest(i=i):
                self.assertEqual(i, i)

    def test_all_failing_subtests(self):
        """All subtests fail."""
        for i in range(2):
            with self.subTest(i=i):
                self.assertEqual(i, i + 1)

    def test_mixed_subtests(self):
        """Mixed passing and failing subtests."""
        for i in range(4):
            with self.subTest(i=i):
                if i % 2 == 0:
                    self.assertEqual(i, i)
                else:
                    self.assertEqual(i, i + 1)

    def test_subtests_with_different_param_types(self):
        """Subtests with different parameter types."""
        test_cases = [
            ("string", 1),
            (42, "string"),
            (True, None),
            ([1, 2], {"key": "value"})
        ]
        for i, (param1, param2) in enumerate(test_cases):
            with self.subTest(index=i, param1=param1, param2=param2):
                self.assertTrue(isinstance(param1, (str, int, bool, list, dict)))

    def test_nested_subtests(self):
        """Nested subtests (this should work as separate subtests)."""
        for i in range(2):
            with self.subTest(outer=i):
                for j in range(2):
                    with self.subTest(inner=j):
                        self.assertEqual(i * j, i * j)

    def test_subtest_with_no_params(self):
        """Subtest with no parameters."""
        for i in range(2):
            with self.subTest():
                self.assertEqual(i, i)


def run_comprehensive_test():
    """Run comprehensive subtest test."""
    # Create temporary directory
    temp_dir = tempfile.mkdtemp()

    try:
        # Run tests with TAPTestRunner
        loader = unittest.TestLoader()
        suite = loader.loadTestsFromTestCase(ComprehensiveSubTestTest)
        runner = TAPTestRunner()
        runner.set_outdir(temp_dir)
        result = runner.run(suite)

        print(f"Test result: {result.testsRun} tests run, {len(result.failures)} failures, {len(result.errors)} errors")

        # Read and analyze TAP content
        tap_files = []
        if os.path.exists(temp_dir):
            for filename in sorted(os.listdir(temp_dir)):
                if filename.endswith('.tap'):
                    filepath = os.path.join(temp_dir, filename)
                    with open(filepath, 'r') as f:
                        content = f.read().strip()
                        tap_files.append((filename, content))

        print(f"TAP files generated: {len(tap_files)}")

        total_tap_lines = 0
        for filename, content in tap_files:
            print(f"\n--- {filename} ---")
            lines = content.split('\n')
            print(f"Lines: {len(lines)}")
            total_tap_lines += len([l for l in lines if l.startswith(('ok ', 'not ok '))])

            # Show first few lines and last few lines
            if len(lines) <= 10:
                for line in lines:
                    print(f"  {line}")
            else:
                print("  First 5 lines:")
                for line in lines[:5]:
                    print(f"    {line}")
                print("  ...")
                print("  Last 5 lines:")
                for line in lines[-5:]:
                    print(f"    {line}")

        print(f"\nTotal test assertions in TAP: {total_tap_lines}")
        print(f"Expected test methods: {result.testsRun}")

        return tap_files, result

    finally:
        # Clean up
        shutil.rmtree(temp_dir, ignore_errors=True)


if __name__ == '__main__':
    run_comprehensive_test()

