"""
Additional edge case tests for the base_schema fix.
"""

from marshmallow import Schema, post_dump
from marshmallow_dataclass import dataclass
from typing import List, Optional


# Test 1: Multiple levels of nesting
class UpperCaseSchema(Schema):
    @post_dump
    def uppercase(self, data, **kwargs):
        return {k.upper(): v for k, v in data.items()}


class DoubleValueSchema(Schema):
    @post_dump
    def double_value(self, data, **kwargs):
        return dict(value=data['value'] * 2)


@dataclass(base_schema=UpperCaseSchema)
class Level1:
    name: str
    value: int


@dataclass(base_schema=DoubleValueSchema)
class Level2:
    level1: Level1
    count: int


@dataclass
class Level3:
    level2: Level2
    flag: bool


# Test 2: Lists of nested dataclasses
@dataclass
class Container:
    items: List[Level1]


# Test 3: Optional nested dataclasses
@dataclass
class OptionalContainer:
    item: Optional[Level1] = None


def test_multilevel_nesting():
    print("Testing multilevel nesting...")
    level1_instance = Level1("test", 5)
    level2_instance = Level2(level1_instance, 10)
    level3_instance = Level3(level2_instance, True)

    result = Level3.Schema().dump(level3_instance)
    print(f"Result: {result}")

    # The Level1 inside should be uppercased due to UpperCaseSchema
    expected_level1_data = {'NAME': 'test', 'VALUE': 5}  # UpperCaseSchema effect
    expected_level2_data = {'level1': expected_level1_data, 'count': 20}  # DoubleValueSchema effect
    expected = {'level2': expected_level2_data, 'flag': True}

    # Actually, let's trace this properly:
    # Level2 uses DoubleValueSchema, which doubles the 'value' field (but there's no 'value', there's 'count')
    # Wait, let me check the DoubleValueSchema - it doubles data['value'], but Level2 has 'count'
    # So DoubleValueSchema won't affect Level2 because it looks for 'value' key

    # Level1 uses UpperCaseSchema, which uppercases all keys
    expected = {'level2': {'level1': {'NAME': 'test', 'VALUE': 5}, 'count': 10}, 'flag': True}

    success = result == expected
    print(f"Expected: {expected}")
    print(f"Success: {success}")
    return success


def test_list_nesting():
    print("\nTesting list nesting...")
    items = [Level1("first", 1), Level1("second", 2)]
    container = Container(items)

    result = Container.Schema().dump(container)
    print(f"Result: {result}")

    # Each Level1 should have uppercased keys
    expected = {'items': [{'NAME': 'first', 'VALUE': 1}, {'NAME': 'second', 'VALUE': 2}]}

    success = result == expected
    print(f"Expected: {expected}")
    print(f"Success: {success}")
    return success


def test_optional_nesting():
    print("\nTesting optional nesting...")

    # Test with None
    container_none = OptionalContainer(None)
    result_none = OptionalContainer.Schema().dump(container_none)
    print(f"With None: {result_none}")
    expected_none = {'item': None}
    success_none = result_none == expected_none

    # Test with actual value
    container_some = OptionalContainer(Level1("optional", 42))
    result_some = OptionalContainer.Schema().dump(container_some)
    print(f"With value: {result_some}")
    expected_some = {'item': {'NAME': 'optional', 'VALUE': 42}}
    success_some = result_some == expected_some

    success = success_none and success_some
    print(f"Success: {success}")
    return success


def main():
    print("Running edge case tests for base_schema fix...")
    print("=" * 60)

    test1_success = test_multilevel_nesting()
    test2_success = test_list_nesting() 
    test3_success = test_optional_nesting()

    all_success = test1_success and test2_success and test3_success

    print("\n" + "=" * 60)
    if all_success:
        print("✅ ALL EDGE CASE TESTS PASSED!")
    else:
        print("❌ SOME EDGE CASE TESTS FAILED!")

    return all_success


if __name__ == '__main__':
    main()

