"""
Test script to verify validation hints are working correctly.
"""

import warnings
import json
from frictionless import Resource

def capture_warnings(func):
    """Capture warnings from a function call"""
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        result = func()
        return result, [warning.message for warning in w]

def test_missing_values_warning():
    """Test that missingValues at resource level produces warning"""
    def create_resource():
        resource_descriptor = {
            "path": "data/table.csv",
            "missingValues": ["", "N/A", "NULL"]
        }
        return Resource(resource_descriptor)

    resource, captured_warnings = capture_warnings(create_resource)

    print("=== Testing missingValues warning ===")
    print(f"Number of warnings: {len(captured_warnings)}")

    missing_values_warnings = [w for w in captured_warnings 
                              if "missingValues" in str(w) and "resource level" in str(w)]

    if missing_values_warnings:
        print("✓ PASS: missingValues warning detected")
        print(f"Warning message: {missing_values_warnings[0]}")
        return True
    else:
        print("✗ FAIL: No missingValues warning detected")
        print("All captured warnings:")
        for i, w in enumerate(captured_warnings):
            print(f"  {i+1}. {w}")
        return False

