    """Test that correct usage produces no warnings"""
    def create_resource():
        resource_descriptor = {
            "path": "data/table.csv",
            "schema": {
                "missingValues": ["", "N/A", "NULL"],
                "fields": [
                    {"name": "id", "type": "integer"},
                    {"name": "name", "type": "string"}
                ]
            }
        }
        return Resource(resource_descriptor)

    resource, captured_warnings = capture_warnings(create_resource)

