def visit_Delete(self, node):
    ast = pkg(node)
    for target in node.targets:
        if isinstance(target, ast.Name):
            # For Name targets, we need to mark the definition as deleted
            defs = self.defs(target, quiet=True)
            for d in defs:
                d.isdeleted = True
        # For other targets (Attribute, Subscript), we still visit them
        # but they don't affect our definition tracking
        else:
            self.visit(target)

