def _strip_whitespace_from_data(self, data: typing.Mapping) -> typing.Mapping:
    """Recursively strip whitespace from string values in the data mapping.

    :param data: The input data mapping
    :return: A new mapping with whitespace stripped from string values
    """
    if not self.strip_whitespace:
        return data

    if not isinstance(data, typing.Mapping):
        return data

    stripped_data = {}
    for key, value in data.items():
        if isinstance(value, str):
            stripped_data[key] = value.strip()
        elif isinstance(value, typing.Mapping):
            # Recursively process nested mappings
            stripped_data[key] = self._strip_whitespace_from_data(value)
        elif isinstance(value, (list, tuple)):
            # Process list/tuple items
            stripped_items = []
            for item in value:
                if isinstance(item, str):
                    stripped_items.append(item.strip())
                elif isinstance(item, typing.Mapping):
                    stripped_items.append(self._strip_whitespace_from_data(item))
                else:
                    stripped_items.append(item)
            stripped_data[key] = type(value)(stripped_items)
        else:
            stripped_data[key] = value

    return stripped_data

