"""
Comprehensive test for the strip_whitespace feature.
This could be integrated into the main test suite.
"""

import pytest
from webargs import fields
from webargs.core import Parser
from unittest import mock


class MockRequestParser(Parser):
    """A minimal parser implementation that parses mock requests."""

    def load_querystring(self, req, schema):
        return self._makeproxy(req.query, schema)

    def load_json(self, req, schema):
        return req.json

    def load_cookies(self, req, schema):
        return req.cookies


def test_strip_whitespace_disabled_by_default():
    """Test that strip_whitespace is disabled by default for backward compatibility."""
    parser = MockRequestParser()
    assert parser.strip_whitespace is False

    args = {"name": fields.Str()}
    request = mock.Mock()
    request.json = {"name": "  John  "}

    result = parser.parse(args, request, location="json")
    assert result["name"] == "  John  "  # Whitespace preserved


def test_strip_whitespace_enabled():
    """Test that strip_whitespace works when enabled."""
    parser = MockRequestParser(strip_whitespace=True)
    assert parser.strip_whitespace is True

    args = {"name": fields.Str()}
    request = mock.Mock()
    request.json = {"name": "  John  "}

    result = parser.parse(args, request, location="json")
    assert result["name"] == "John"  # Whitespace stripped


def test_strip_whitespace_json():
    """Test whitespace stripping for JSON data."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {
        "first_name": fields.Str(required=True),
        "last_name": fields.Str(),
        "bio": fields.Str()
    }

    request = mock.Mock()
    request.json = {
        "first_name": "  John  ",
        "last_name": "  Doe  ",
        "bio": "  Software Engineer  "
    }

    result = parser.parse(args, request, location="json")
    assert result["first_name"] == "John"
    assert result["last_name"] == "Doe"
    assert result["bio"] == "Software Engineer"


def test_strip_whitespace_querystring():
    """Test whitespace stripping for query string data."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {"name": fields.Str()}
    request = mock.Mock()
    request.query = {"name": "  Jane  "}

    result = parser.parse(args, request, location="query")
    assert result["name"] == "Jane"


def test_strip_whitespace_nested_dict():
    """Test whitespace stripping in nested dictionaries."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {
        "user": fields.Nested({
            "name": fields.Str(required=True),
            "email": fields.Str()
        })
    }

    request = mock.Mock()
    request.json = {
        "user": {
            "name": "  John Doe  ",
            "email": "  john@example.com  "
        }
    }

    result = parser.parse(args, request, location="json")
    assert result["user"]["name"] == "John Doe"
    assert result["user"]["email"] == "john@example.com"


def test_strip_whitespace_list_of_strings():
    """Test whitespace stripping for lists of strings."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {"tags": fields.List(fields.Str())}
    request = mock.Mock()
    request.json = {"tags": ["  python  ", "  web  ", "  development  "]}

    result = parser.parse(args, request, location="json")
    assert result["tags"] == ["python", "web", "development"]


def test_strip_whitespace_list_of_nested_objects():
    """Test whitespace stripping for lists of nested objects."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {
        "users": fields.List(fields.Nested({
            "first_name": fields.Str(),
            "last_name": fields.Str()
        }))
    }

    request = mock.Mock()
    request.json = {
        "users": [
            {"first_name": "  John  ", "last_name": "  Doe  "},
            {"first_name": "  Jane  ", "last_name": "  Smith  "}
        ]
    }

    result = parser.parse(args, request, location="json")
    assert result["users"][0]["first_name"] == "John"
    assert result["users"][0]["last_name"] == "Doe"
    assert result["users"][1]["first_name"] == "Jane"
    assert result["users"][1]["last_name"] == "Smith"


def test_strip_whitespace_edge_cases():
    """Test edge cases for whitespace stripping."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {
        "empty_string": fields.Str(),
        "spaces_only": fields.Str(),
        "tabs_only": fields.Str(),
        "mixed_whitespace": fields.Str(),
        "no_whitespace": fields.Str()
    }

    request = mock.Mock()
    request.json = {
        "empty_string": "",
        "spaces_only": "   ",
        "tabs_only": "\t\t\t",
        "mixed_whitespace": " \t \n ",
        "no_whitespace": "hello"
    }

    result = parser.parse(args, request, location="json")
    assert result["empty_string"] == ""
    assert result["spaces_only"] == ""
    assert result["tabs_only"] == ""
    assert result["mixed_whitespace"] == ""
    assert result["no_whitespace"] == "hello"


def test_strip_whitespace_non_string_fields():
    """Test that non-string fields are unaffected."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {
        "name": fields.Str(),
        "age": fields.Int(),
        "active": fields.Bool(),
        "scores": fields.List(fields.Int())
    }

    request = mock.Mock()
    request.json = {
        "name": "  John  ",
        "age": 30,
        "active": True,
        "scores": [100, 95, 87]
    }

    result = parser.parse(args, request, location="json")
    assert result["name"] == "John"  # Stripped
    assert result["age"] == 30  # Unchanged
    assert result["active"] is True  # Unchanged
    assert result["scores"] == [100, 95, 87]  # Unchanged


def test_strip_whitespace_mixed_content():
    """Test mixed content with some strings and some non-strings."""
    parser = MockRequestParser(strip_whitespace=True)

    args = {
        "user": fields.Nested({
            "name": fields.Str(),
            "age": fields.Int(),
            "tags": fields.List(fields.Str()),
            "settings": fields.Nested({
                "theme": fields.Str(),
                "notifications": fields.Bool()
            })
        }),
        "metadata": fields.List(fields.Nested({
            "key": fields.Str(),
            "value": fields.Str()
        }))
    }

    request = mock.Mock()
    request.json = {
        "user": {
            "name": "  John Doe  ",
            "age": 30,
            "tags": ["  python  ", "  web  "],
            "settings": {
                "theme": "  dark  ",
                "notifications": True
            }
        },
        "metadata": [
            {"key": "  author  ", "value": "  John  "},
            {"key": "  version  ", "value": "  1.0  "}
        ]
    }

    result = parser.parse(args, request, location="json")

    # Check nested user object
    assert result["user"]["name"] == "John Doe"
    assert result["user"]["age"] == 30  # Unchanged
    assert result["user"]["tags"] == ["python", "web"]
    assert result["user"]["settings"]["theme"] == "dark"
    assert result["user"]["settings"]["notifications"] is True  # Unchanged

    # Check metadata list
    assert result["metadata"][0]["key"] == "author"
    assert result["metadata"][0]["value"] == "John"
    assert result["metadata"][1]["key"] == "version"
    assert result["metadata"][1]["value"] == "1.0"


if __name__ == "__main__":
    # Run tests manually
    test_strip_whitespace_disabled_by_default()
    test_strip_whitespace_enabled()
    test_strip_whitespace_json()
    test_strip_whitespace_querystring()
