def process(self, resources):
    client = local_session(self.manager.session_factory).client('ec2')
    params = dict(self.data)
    params.pop('type')

    if self.data.get('state'):
        params.pop('state')

    model = self.manager.get_model()
    params['ResourceIds'] = [r[model.id] for r in resources]

    if not self.state:
        self.delete_flow_logs(client, params['ResourceIds'])
        return

    params['ResourceType'] = self.RESOURCE_ALIAS[model.arn_type]
    params['TrafficType'] = self.data.get('TrafficType', 'ALL').upper()
    params['MaxAggregationInterval'] = self.data.get('MaxAggregationInterval', 600)

    # Check if we should auto-create CloudWatch Log Group
    destination_type = self.data.get('LogDestinationType', 'cloud-watch-logs')
    should_create_log_group = (
        destination_type == 'cloud-watch-logs' and 
        'LogGroupName' in params and params['LogGroupName']
    )

    if should_create_log_group:
        self._ensure_log_group_exists(params['LogGroupName'])

    try:
        results = client.create_flow_logs(**params)

        for r in results['Unsuccessful']:
            self.log.exception(
                'Exception: create flow-log for %s: %s',
                r['ResourceId'], r['Error']['Message'])
    except ClientError as e:
        if e.response['Error']['Code'] == 'FlowLogAlreadyExists':
            self.log.exception(
                'Exception: create flow-log: %s',
                e.response['Error']['Message'])
        else:
            raise

def _ensure_log_group_exists(self, log_group_name):
    """Ensure CloudWatch Log Group exists, create it if it doesn't."""
    logs_client = local_session(self.manager.session_factory).client('logs')

    # Check if log group already exists by listing and matching exactly
    try:
        paginator = logs_client.get_paginator('describe_log_groups')
        for page in paginator.paginate():
            for log_group in page.get('logGroups', []):
                if log_group['logGroupName'] == log_group_name:
                    return  # Log group already exists
    except Exception:
        # If we can't list log groups due to permissions, proceed to create attempt
        pass

    # Log group doesn't exist, create it
    try:
        logs_client.create_log_group(logGroupName=log_group_name)
        self.log.info('Created CloudWatch Log Group: %s', log_group_name)
    except ClientError as e:
        # If it already exists (race condition), that's fine
        if e.response['Error']['Code'] != 'ResourceAlreadyExistsException':
            self.log.error('Failed to create CloudWatch Log Group %s: %s', 
                          log_group_name, e.response['Error']['Message'])
            raise

