#!/usr/bin/env python3

"""
Unit test to verify the _ensure_log_group_exists method works correctly.
This test bypasses the placebo recording mechanism.
"""

import unittest
from unittest.mock import Mock, patch, MagicMock
from c7n.resources.vpc import CreateFlowLogs
from c7n.exceptions import ClientError


class TestLogGroupCreation(unittest.TestCase):

    def setUp(self):
        """Set up test fixtures"""
        self.manager = Mock()
        self.manager.session_factory = Mock()
        self.action = CreateFlowLogs({'test': True}, {
            'type': 'set-flow-log',
            'DeliverLogsPermissionArn': 'arn:aws:iam::123456789012:role/test-role',
            'LogGroupName': '/aws/vpc/flowlogs/test'
        })
        self.action.manager = self.manager

    @patch('c7n.resources.vpc.local_session')
    def test_ensure_log_group_exists_when_exists(self, mock_local_session):
        """Test that method returns early when log group already exists"""
        # Setup mock logs client
        mock_logs_client = Mock()
        mock_local_session.return_value.client.return_value = mock_logs_client

        # Mock describe_log_groups to return our log group
        mock_logs_client.get_paginator.return_value.paginate.return_value = [
            {
                'logGroups': [
                    {'logGroupName': '/aws/vpc/flowlogs/test'},
                    {'logGroupName': '/aws/lambda/other'}
                ]
            }
        ]

        # Call the method
        self.action._ensure_log_group_exists('/aws/vpc/flowlogs/test')

        # Verify describe_log_groups was called
        mock_logs_client.get_paginator.assert_called_once_with('describe_log_groups')
        # Verify create_log_group was NOT called
        mock_logs_client.create_log_group.assert_not_called()

    @patch('c7n.resources.vpc.local_session')
    def test_ensure_log_group_exists_when_not_exists(self, mock_local_session):
        """Test that method creates log group when it doesn't exist"""
        # Setup mock logs client
        mock_logs_client = Mock()
        mock_local_session.return_value.client.return_value = mock_logs_client

        # Mock describe_log_groups to return empty list
        mock_logs_client.get_paginator.return_value.paginate.return_value = [
            {'logGroups': [{'logGroupName': '/aws/lambda/other'}]},
            {'logGroups': [{'logGroupName': '/aws/apigateway/another'}]}
        ]

        # Mock successful creation
        mock_logs_client.create_log_group.return_value = {}

        # Call the method
        self.action._ensure_log_group_exists('/aws/vpc/flowlogs/test')

        # Verify describe_log_groups was called
        mock_logs_client.get_paginator.assert_called_once_with('describe_log_groups')
        # Verify create_log_group WAS called
        mock_logs_client.create_log_group.assert_called_once_with(
            logGroupName='/aws/vpc/flowlogs/test'
        )

    @patch('c7n.resources.vpc.local_session')
    def test_ensure_log_group_exists_when_already_exists_race_condition(self, mock_local_session):
        """Test that method handles race condition gracefully"""
        # Setup mock logs client
        mock_logs_client = Mock()
        mock_local_session.return_value.client.return_value = mock_logs_client

        # Mock describe_log_groups to return empty list (initial check)
        mock_logs_client.get_paginator.return_value.paginate.return_value = [
            {'logGroups': []}
        ]

        # Mock create_log_group to raise ResourceAlreadyExistsException
        error_response = {
            'Error': {
                'Code': 'ResourceAlreadyExistsException',
                'Message': 'The specified log group already exists'
            }
        }
        mock_logs_client.create_log_group.side_effect = ClientError(error_response, 'CreateLogGroup')

        # Call the method - should not raise exception
        self.action._ensure_log_group_exists('/aws/vpc/flowlogs/test')

        # Verify the calls were made
        mock_logs_client.get_paginator.assert_called_once_with('describe_log_groups')
        mock_logs_client.create_log_group.assert_called_once_with(
            logGroupName='/aws/vpc/flowlogs/test'
        )

    @patch('c7n.resources.vpc.local_session')
    def test_ensure_log_group_exists_when_create_fails(self, mock_local_session):
        """Test that method propagates other creation errors"""
        # Setup mock logs client
        mock_logs_client = Mock()
        mock_local_session.return_value.client.return_value = mock_logs_client

        # Mock describe_log_groups to return empty list
        mock_logs_client.get_paginator.return_value.paginate.return_value = [
            {'logGroups': []}
        ]

        # Mock create_log_group to raise a different exception
        error_response = {
            'Error': {
                'Code': 'AccessDeniedException',
                'Message': 'User is not authorized to perform create_log_group'
            }
        }
        mock_logs_client.create_log_group.side_effect = ClientError(error_response, 'CreateLogGroup')

        # Call the method - should raise exception
        with self.assertRaises(ClientError) as context:
            self.action._ensure_log_group_exists('/aws/vpc/flowlogs/test')

        self.assertEqual(context.exception.response['Error']['Code'], 'AccessDeniedException')


if __name__ == '__main__':
    unittest.main()

