"""
Test for the decodeURIComponent fix in YouTube signature extraction.
This test verifies that the fix prevents incorrectly extracting built-in 
JavaScript functions as signature function names.
"""

import unittest
import re
import sys
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from yt_dlp.extractor.youtube import YoutubeIE
from yt_dlp import YoutubeDL


class TestDecodeURIComponentFix(unittest.TestCase):

    def setUp(self):
        self.ydl = YoutubeDL({})
        self.ie = YoutubeIE(self.ydl)

    def test_problematic_pattern_fixed(self):
        """Test that the problematic pattern no longer matches built-in functions"""

        # The fixed pattern from line 3126
        fixed_pattern = r'\bc&&\(c=(?P<sig>(?!encodeURIComponent|decodeURIComponent)[a-zA-Z0-9$]{2,})\(decodeURIComponent\(c\)\)'

        # Cases that should NOT match (would have matched incorrectly before the fix)
        problematic_cases = [
            'c&&(c=decodeURIComponent(decodeURIComponent(c)))',
            'c&&(c=encodeURIComponent(decodeURIComponent(c)))',
            'c&&(c=decodeURIComponent(encodeURIComponent(c)))',
        ]

        for case in problematic_cases:
            match = re.search(fixed_pattern, case)
            self.assertIsNone(match, f"Pattern should not match: {case}")

    def test_valid_patterns_still_work(self):
        """Test that valid signature function patterns still match correctly"""

        # The fixed pattern from line 3126
        fixed_pattern = r'\bc&&\(c=(?P<sig>(?!encodeURIComponent|decodeURIComponent)[a-zA-Z0-9$]{2,})\(decodeURIComponent\(c\)\)'

        # Valid cases that should still match
        valid_cases = [
            ('c&&(c=aa(decodeURIComponent(c)))', 'aa'),
            ('c&&(c=sigFunc123(decodeURIComponent(c)))', 'sigFunc123'),
            ('c&&(c=$ABC$123(decodeURIComponent(c)))', '$ABC$123'),
            ('c&&(c=_privateFunc(decodeURIComponent(c)))', '_privateFunc'),
        ]

        for js_code, expected_func in valid_cases:
            match = re.search(fixed_pattern, js_code)
            self.assertIsNotNone(match, f"Pattern should match: {js_code}")
            self.assertEqual(match.group('sig'), expected_func, 
                           f"Expected function name '{expected_func}' but got '{match.group('sig')}'")

    def test_parse_sig_js_with_problematic_js(self):
        """Test _parse_sig_js method with JavaScript that contains problematic patterns"""

        # Create JavaScript code that would have caused the issue before the fix
        problematic_js = '''
        // Some YouTube player code
        var someFunction = function(a) {
            return a.split("").reverse().join("");
        };

        // This pattern would have caused the old regex to incorrectly extract 'decodeURIComponent'
        var nestedCalls = decodeURIComponent(decodeURIComponent(someData));

        // This is a legitimate signature function
        var realSigFunc = function(a) {
            a = a.split("");
            // signature operations
            return a.join("");
        };

        // This pattern should match realSigFunc, not decodeURIComponent
        c&&(c=realSigFunc(decodeURIComponent(c)));
        '''

        # This should not raise an exception anymore
        try:
            funcname = self.ie._search_regex(
                r'\bc&&\(c=(?P<sig>(?!encodeURIComponent|decodeURIComponent)[a-zA-Z0-9$]{2,})\(decodeURIComponent\(c\)\)',
                problematic_js, 'test', group='sig')
            self.assertEqual(funcname, 'realSigFunc')
        except Exception:
            self.fail("_search_regex should find 'realSigFunc' and not fail")


if __name__ == '__main__':
    unittest.main()

