def _create_polygon_from_input(
    polygon_input: Any, holes: Optional[List[Any]] = None
) -> shapely.Polygon:
    """Convince function to create a shapely.Polygon from different input types.

    Can create a shapely.Polygon from:
        - list of coordinates
        - list of shapely.Points
        - shapely.Polygon
        - shapely.GeometryCollection (containing only polygons)
        - WKT-string (including GeometryCollection WKT)

    Args:
        polygon_input: input which can used to assemble a shapely.Polygon
        holes (optional): List of objects which represent holes in the
            shapely.Polygon. May not be used, when polygon_input is a
            shapely.Polygon, shapely.GeometryCollection or WKT.

    Returns:
        shapely.Polygon constructed by the input
    """
    return_poly = None
    if isinstance(polygon_input, shapely.Polygon):
        if holes is not None:
            raise GeometryError(
                "If polygon is of type shapely.Polygon additional holes are not allowed"
            )
        return_poly = polygon_input
    elif isinstance(polygon_input, shapely.GeometryCollection):
        if holes is not None:
            raise GeometryError(
                "If polygon is of type shapely.GeometryCollection additional holes are not allowed"
            )

        # Check that all geometries in the collection are polygons
        if not all(isinstance(geom, shapely.Polygon) for geom in polygon_input.geoms):
            raise GeometryError(
                "GeometryCollection must contain only polygons"
            )

        # Create union of all polygons
        try:
            return_poly = shapely.union_all(list(polygon_input.geoms))
        except Exception as exc:
            raise GeometryError(
                f"Could not create polygon from the given GeometryCollection: {polygon_input}."
            ) from exc

        # Convert to polygon if it's a multipolygon with one polygon
        if hasattr(return_poly, 'geoms') and len(return_poly.geoms) == 1:
            return_poly = return_poly.geoms[0]
        elif hasattr(return_poly, 'geoms') and len(return_poly.geoms) > 1:
            raise GeometryError(
                "Union of GeometryCollection polygons must result in a single polygon"
            )
    elif isinstance(polygon_input, str):
        if holes is not None:
            raise GeometryError(
                "If polygon is of type WKT additional holes are not allowed"
            )
