def find_var_names(ds_reference_dict: KerchunkStoreRefs) -> list[str]:
    """Find the names of zarr variables in this store/group."""

    refs = ds_reference_dict["refs"]

    # Find actual variables by looking for .zarray entries at the top level
    # A variable is identified by having a .zarray key in the refs where the path has only one component
    var_names = set()
    for key in refs.keys():
        if key.endswith("/.zarray"):
            # Extract the variable path by removing the trailing "/.zarray"
            var_path = key[:-8]  # Remove "/.zarray"
            # Only include if this is a top-level variable (no slashes in the remaining path)
