def setupTable_meta(self):
    """
    Compile the meta table.

    **This should not be called externally.**
    """
    if "meta" not in self.tables:
        return

    meta_data = self.ufo.lib.get(OPEN_TYPE_META_KEY)
    if not meta_data:
        return

    # Create meta table
    from fontTools.ttLib import newTable
    meta = self.otf["meta"] = newTable("meta")

    # Initialize data dictionary
    meta.data = {}

    # Process known metadata tags
    # dlng: Design languages (tag = 0x646C6E67)
    if "dlng" in meta_data:
        dlng_value = meta_data["dlng"]
        if isinstance(dlng_value, str):
            # Convert string to bytes
            meta.data[0x646C6E67] = dlng_value.encode("utf-8")

