    """
    Enhanced SecretStr implementation that plays nicely with string operations.

    This class wraps Pydantic's SecretStr but adds support for string concatenation
    and other string operations while maintaining the security of keeping secrets
    masked in representations.

    Examples:
        >>> from koheesio.models import SecretStr
        >>> body = SecretStr("foobarbazbladibla")
        >>> type_header = "bearer"
        >>> header = type_header + body  # Works!
        >>> header = f"{type_header} {body}"  # Also works!
    """

    def __init__(self, secret_value: str):
        """Initialize SecretStr with a secret value."""
        self._secret_value = PydanticSecretStr(secret_value)

    def get_secret_value(self) -> str:
        """Get the actual secret value."""
        return self._secret_value.get_secret_value()

    def __str__(self) -> str:
        """Return masked representation for safety."""
        return str(self._secret_value)

    def __repr__(self) -> str:
        """Return masked representation for safety."""
        return repr(self._secret_value)

    def __add__(self, other) -> str:
        """
        Support concatenation with strings.

        When SecretStr is on the left side of + operator with a string,
        returns a regular string with the secret masked.
        """
        if isinstance(other, str):
            return str(self) + other
        elif isinstance(other, SecretStr):
            return str(self) + str(other)
        else:
            return NotImplemented

    def __radd__(self, other) -> str:
        """
        Support reverse concatenation with strings.

        When SecretStr is on the right side of + operator with a string,
        returns a regular string with the secret masked.
        """
        if isinstance(other, str):
            return other + str(self)
        else:
            return NotImplemented

    # Pydantic serialization support
    @classmethod
    def __get_pydantic_core_schema__(cls, _source_type, _handler):
        """Support Pydantic serialization."""
        from pydantic_core import core_schema
        return core_schema.union_schema([
            core_schema.str_schema(),
            core_schema.is_instance_schema(cls),
        ])

    @classmethod
    def __get_pydantic_json_schema__(cls, _schema, handler):
        """Support Pydantic JSON schema generation."""
        return handler(str)


