"""
Comprehensive test to verify the fix handles various edge cases correctly.
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

import bibmanager.bib_manager as bm

def test_edge_cases():
    """Test various edge cases for ISBN+DOI duplicate detection."""

    print("Testing edge cases for ISBN+DOI duplicate detection...")

    # Test Case 1: Same ISBN, different DOIs (original issue)
    entry1 = '''@incollection{test1,
        isbn = {1234567890},
        doi = {10.1234/abc}
    }'''

    entry2 = '''@incollection{test2,
        isbn = {1234567890},
        doi = {10.1234/def}
    }'''

    result = bm.merge(new=[bm.Bib(entry1)], base=[bm.Bib(entry2)], take='old')
    assert len(result) == 2, f"Expected 2 entries, got {len(result)}"
    print("✓ Test 1 passed: Different DOIs preserved")

    # Test Case 2: Same ISBN, same DOIs (should be treated as duplicate)
    entry3 = '''@incollection{test3,
        isbn = {1234567890},
        doi = {10.1234/abc}
    }'''

    entry4 = '''@incollection{test4,
        isbn = {1234567890},
        doi = {10.1234/abc}
    }'''

    result = bm.merge(new=[bm.Bib(entry3)], base=[bm.Bib(entry4)], take='old')
    assert len(result) == 1, f"Expected 1 entry (duplicate), got {len(result)}"
    print("✓ Test 2 passed: Same DOIs treated as duplicate")

    # Test Case 3: Same ISBN, one with DOI, one without (should be treated as duplicate)
    entry5 = '''@incollection{test5,
        isbn = {1234567890},
        doi = {10.1234/abc}
    }'''

    entry6 = '''@incollection{test6,
        isbn = {1234567890}
    }'''

    result = bm.merge(new=[bm.Bib(entry5)], base=[bm.Bib(entry6)], take='old')
    assert len(result) == 1, f"Expected 1 entry (duplicate), got {len(result)}"
    print("✓ Test 3 passed: DOI vs no DOI treated as duplicate")

    # Test Case 4: Same ISBN, both without DOIs (should be treated as duplicate)
    entry7 = '''@incollection{test7,
        isbn = {1234567890}
    }'''

    entry8 = '''@incollection{test8,
        isbn = {1234567890}
    }'''

    result = bm.merge(new=[bm.Bib(entry7)], base=[bm.Bib(entry8)], take='old')
    assert len(result) == 1, f"Expected 1 entry (duplicate), got {len(result)}"
    print("✓ Test 4 passed: No DOIs treated as duplicate")

    # Test Case 5: Different ISBN (should not be treated as duplicate regardless of DOI)
    entry9 = '''@incollection{test9,
        isbn = {1234567890},
        doi = {10.1234/abc}
    }'''

    entry10 = '''@incollection{test10,
        isbn = {0987654321},
        doi = {10.1234/abc}
    }'''

    result = bm.merge(new=[bm.Bib(entry9)], base=[bm.Bib(entry10)], take='old')
    assert len(result) == 2, f"Expected 2 entries, got {len(result)}"
    print("✓ Test 5 passed: Different ISBNs preserved")

    # Test Case 6: Original issue example with LaTeX escapes
    db_entry = '''@incollection{OConnor2017,
        isbn = "9783319218465",
        doi = "10.1007/978-3-319-20794-0{\\_}129-1"
    }'''

    new_entry = '''@incollection{Alsabti2016,
        isbn = {9783319218465},
        doi = {10.1007/978-3-319-21846-5{\_}1}
    }'''

    result = bm.merge(new=[bm.Bib(db_entry)], base=[bm.Bib(new_entry)], take='old')
    assert len(result) == 2, f"Expected 2 entries, got {len(result)}"
    print("✓ Test 6 passed: Original issue example with LaTeX escapes")

    print("\nAll edge case tests passed! ✓")

if __name__ == "__main__":
    test_edge_cases()

