#!/usr/bin/env python
"""
Test the specific issue mentioned - other color schemes with reversescale=True
"""

import plotly.figure_factory as ff

def test_issue_scenario():
    print("Testing the specific issue scenario...")

    # Use data where values are close to zero to see the blending issue
    z_data = [[-0.1, 0, 0.1], [-0.05, 0.05, 0.15]]

    print("Z values:")
    for row in z_data:
        print([f"{val:6.2f}" for val in row])

    # Test case 1: Default behavior (should work fine according to issue)
    print("\n1. Default RdBu (should work fine):")
    fig1 = ff.create_annotated_heatmap(z_data)
    annotations = fig1['layout']['annotations']
    for i, (row, ann_row) in enumerate(zip(z_data, [annotations[0:3], annotations[3:6]])):
        for j, (val, ann) in enumerate(zip(row, ann_row)):
            print(f"  Value {val:6.2f} -> font: {ann['font']['color']}")

    # Test case 2: Other standard color schemes with reversescale=True
    # This is where the issue should occur
    color_schemes = ['Greys', 'Blues', 'Greens', 'Reds']

    for scheme in color_schemes:
        print(f"\n2. {scheme} with reversescale=True:")
        try:
            fig = ff.create_annotated_heatmap(z_data, colorscale=scheme, reversescale=True)
            annotations = fig['layout']['annotations']
            for i, (row, ann_row) in enumerate(zip(z_data, [annotations[0:3], annotations[3:6]])):
                for j, (val, ann) in enumerate(zip(row, ann_row)):
                    print(f"  Value {val:6.2f} -> font: {ann['font']['color']}")
        except Exception as e:
            print(f"  Error: {e}")

if __name__ == "__main__":
    test_issue_scenario()

